INSERT INTO amb_quesitos (
    norma_versao_id,
    codigo,
    numero,
    titulo,
    texto,
    ordem,
    ativo
)
SELECT
    n.id,
    v.codigo,
    v.numero,
    v.titulo,
    v.texto,
    v.ordem,
    TRUE
FROM (VALUES
    ('Q01', 1, 'Localização e regularidade ambiental', 'A atividade será implantada e desenvolvida em área já antropizada ou consolidada, sem supressão de vegetação nativa, intervenção em Área de Preservação Permanente, Reserva Legal, área úmida ou outra área ambientalmente protegida, e sem que sua implantação ou operação dependa de licença, autorização, outorga, anuência ou outro ato ambiental prévio?', 1),
    ('Q02', 2, 'Atividade restrita ao cultivo', 'A atividade ficará restrita ao cultivo, aos tratos culturais e à colheita, sem beneficiamento, secagem, defumação, descaroçamento, maceração, produção de silagem, tratamento de sementes, armazenamento comercial ou depósito de agrotóxicos sujeito a controle ambiental específico?', 2),
    ('Q03', 3, 'Operações compreendidas no cultivo', 'A atividade ficará restrita ao cultivo e às operações complementares realizadas com a produção própria, inclusive em ambiente protegido ou sistema hidropônico, sem processamento industrial, fabricação ou compostagem comercial de substratos ou depósito comercial de agrotóxicos sujeito a controle ambiental específico?', 3),
    ('Q04', 4, 'Cultivo e preparo primário da produção', 'A atividade ficará restrita ao cultivo, aos tratos culturais, à colheita e ao preparo primário da produção própria, sem fabricação de alimentos ou bebidas, beneficiamento industrial, torrefação, moagem, sapeco, secagem térmica, trituração, armazenamento comercial ou depósito de agrotóxicos sujeito a controle ambiental específico?', 4),
    ('Q05', 5, 'Produção de sementes e mudas', 'A atividade ficará restrita à produção de sementes ou mudas e às operações de cultivo, colheita, limpeza, seleção, classificação, secagem, acondicionamento e armazenamento temporário da produção própria, sem tratamento com agrotóxicos ou outros produtos químicos, beneficiamento industrial, armazenamento comercial ou depósito de agrotóxicos sujeito a controle ambiental específico?', 5),
    ('Q06', 6, 'Pecuária extensiva', 'A criação será realizada em regime extensivo, com os animais mantidos predominantemente em pastagens, sem confinamento ou alojamento permanente com concentração de animais e dejetos, sem lavagem de instalações que gere efluente não sanitário e sem sistema de armazenamento ou tratamento de dejetos?', 6),
    ('Q07', 7, 'Apicultura e meliponicultura', 'A atividade ficará restrita à apicultura ou meliponicultura e à extração primária dos produtos da própria criação, sem beneficiamento industrial, fabricação de alimentos, bebidas ou cosméticos, prestação de serviço de captura ou remoção de enxames ou manejo de colônias de abelhas nativas sujeito a autorização ambiental?', 7),
    ('Q08', 8, 'Criação de animais de baixo impacto', 'A atividade ficará restrita à criação de animais de estimação, escargô ou bicho-da-seda, sem criação, manejo ou comércio de fauna silvestre sujeita a autorização ambiental, biotério, produção de vacinas ou soros, abate ou processamento industrial, e com manejo dos dejetos, resíduos e águas de limpeza sem lançamento no solo, na rede pluvial ou em corpo hídrico?', 8),
    ('Q09', 9, 'Serviços agrícolas e florestais de baixo impacto', 'Os serviços ficarão restritos à assistência técnica, inventário, monitoramento, inspeção, poda, preparo de terreno, plantio, cultivo ou colheita agrícola em áreas já consolidadas, sem aplicação de agrotóxicos ou outros produtos para controle de pragas, queima, terraplenagem, abertura de novas áreas, corte ou derrubada de vegetação nativa ou outra supressão de vegetação?', 9),
    ('Q10', 10, 'outras atividades de apoio à agricultura', 'A atividade ficará restrita ao apoio agrícola com mão de obra, máquinas ou equipamentos com operador, mecanização, agricultura de precisão, monitoramento ou drones, sem pulverização ou aplicação de agrotóxicos, operação de irrigação sujeita a licenciamento ou outorga, modificação artificial do tempo, manutenção ou lavagem de equipamentos, abastecimento ou armazenamento de combustíveis no estabelecimento?', 10),
    ('Q11', 11, 'Serviços de apoio à reprodução e à pecuária', 'A atividade ficará restrita à prestação de serviços de inseminação artificial, fertilização in vitro, classificação, apanha ou sexagem de animais, ferrageamento, fornecimento de mão de obra ou serviços semelhantes, sem laboratório veterinário, alojamento ou estabulação de animais, limpeza de instalações com carrapaticidas ou sarnicidas, geração de efluentes não sanitários, armazenamento de material biológico ou produtos químicos sujeito a controle ambiental específico e sem depender de licença, autorização ou outro ato ambiental prévio?', 11),
    ('Q12', 12, 'Extração de produtos de florestas plantadas', 'A atividade ficará restrita à extração de madeira em bruto ou à coleta e extração de cascas, folhas, resinas e outros produtos de florestas plantadas, sem serraria, desdobramento ou resserragem de madeira, carbonização, fabricação de tanino, destilação, tratamento químico, produção de óleos ou outro beneficiamento industrial no local?', 12),
    ('Q13', 13, 'Coleta de produtos não madeireiros', 'A atividade ficará restrita à coleta de produtos florestais não madeireiros, sem corte, derrubada, supressão ou prática que cause a morte do indivíduo vegetal, sem coleta de palmito ou de espécies ameaçadas de extinção, observados os limites legais aplicáveis e sem depender de licença, autorização ou outro ato ambiental prévio?', 13),
    ('Q14', 14, 'Conservação e recuperação de florestas nativas', 'A atividade ficará restrita ao florestamento, reflorestamento, condução da regeneração natural, conservação da vegetação e tratos silviculturais destinados à recuperação ou manutenção ambiental, sem exploração comercial de produtos florestais, supressão de vegetação nativa, terraplenagem, intervenção em recursos hídricos ou outra operação que dependa de licença, autorização, anuência ou outro ato ambiental prévio?', 14),
    ('Q15', 15, 'Atividades de apoio à pesca', 'A atividade ficará restrita à prestação de serviços administrativos, técnicos ou logísticos de apoio à pesca, sem captura, coleta, manejo ou soltura de organismos aquáticos, operação de embarcação pesqueira, desembarque, abate, conservação, beneficiamento ou armazenamento de pescado, manutenção, lavagem ou abastecimento de embarcações e sem depender de licença, autorização ou outro ato ambiental prévio?', 15),
    ('Q16', 16, 'Atividades de apoio à aquicultura', 'A atividade ficará restrita à prestação de serviços administrativos, técnicos, de consultoria, monitoramento ou logística de apoio à aquicultura, sem operar estruturas de cultivo, criar, reproduzir, introduzir, soltar, manejar, despescar, beneficiar ou armazenar organismos aquáticos, captar água, lançar efluentes, intervir em recursos hídricos, armazenar produtos químicos, medicamentos ou combustíveis ou depender de licença, autorização, outorga, anuência ou outro ato ambiental prévio?', 16),
    ('Q17', 17, 'Preparação de subprodutos do abate', 'A atividade ficará restrita à preparação de subprodutos de origem animal, sem abate no estabelecimento, fabricação de farinhas de origem animal, graxaria ou processamento industrial de gorduras?', 17),
    ('Q18', 18, 'Preservação do pescado', 'A atividade ficará restrita à limpeza, evisceração, corte, filetagem, resfriamento, refrigeração ou congelamento de pescado, sem fabricação de conservas, farinhas, alimentos para animais, óleos, gorduras ou outros produtos derivados?', 18),
    ('Q19', 19, 'Produção de óleos e gorduras vegetais de baixo impacto', 'A atividade ficará restrita à extração mecânica, prensagem, decantação, filtração, mistura, emulsificação, refino físico e acondicionamento de óleos e gorduras vegetais, sem utilização de solventes orgânicos, refino químico, hidrogenação, interesterificação, graxaria ou processamento de matéria animal?', 19),
    ('Q20', 20, 'Fabricação de alimentos para animais de baixo impacto', 'A atividade ficará restrita à moagem, dosagem, mistura, homogeneização, peletização, extrusão e acondicionamento de matérias-primas vegetais, minerais ou ingredientes secos previamente beneficiados, sem processamento de carcaças, sangue, vísceras, tecidos, resíduos de abate ou matéria animal in natura, fabricação de farinhas de origem animal, graxaria, produção de medicamentos veterinários ou utilização de substâncias sujeitas a controle ambiental específico?', 20),
    ('Q21', 21, 'Fabricação de alimentos por processo de baixo impacto', 'A atividade ficará restrita a operações convencionais de preparação, mistura, cocção, assamento, moagem, modelagem, fermentação alimentar simples, resfriamento, congelamento, secagem, envase ou acondicionamento, sem extração ou síntese química, utilização de solventes, refino, fabricação de fermentos, leveduras ou adoçantes, processamento primário de cacau, processamento de carcaças ou subprodutos animais, enlatamento, esterilização industrial, liofilização industrial ou outro processo sujeito a controle ambiental específico?', 21),
    ('Q22', 22, 'Fabricação de filtros para cigarros', 'A atividade ficará restrita à fabricação de filtros para cigarros, sem utilização de solventes, adesivos, plastificantes ou outros produtos químicos em quantidade ou condição sujeita a controle ambiental específico?', 22),
    ('Q23', 23, 'Preparação, fiação, tecelagem e fabricação de tecidos de malha', 'A atividade ficará restrita a operações mecânicas de preparação, abertura, cardação, penteação, fiação, torção, fabricação de fios ou linhas, tecelagem ou fabricação de tecidos de malha, sem processos úmidos de beneficiamento ou acabamento?', 23),
    ('Q24', 24, 'Acabamentos têxteis secos', 'A atividade ficará restrita a acabamentos têxteis secos, mecânicos ou térmicos, sem lavagem, alvejamento, tingimento, impregnação ou outro processo úmido?', 24),
    ('Q25', 25, 'Fabricação de artefatos têxteis por processo simples', 'A atividade ficará restrita à confecção, corte, costura, enchimento, montagem, tecelagem, entrançamento, torção, bordado ou formação mecânica simples de artefatos têxteis, utilizando materiais previamente produzidos?', 25),
    ('Q26', 26, 'Confecção e montagem por processo seco', 'A atividade ficará restrita à modelagem, corte, costura, pesponto, tricotagem, rebitagem, montagem, fixação, prensagem, recorte ou acabamento mecânico de materiais e componentes previamente produzidos e acabados, sem fabricação ou preparação das matérias-primas?', 26),
    ('Q27', 27, 'Fabricação artesanal', 'A atividade será realizada de forma artesanal, predominantemente manual ou com equipamentos de pequena escala, com até 10 funcionários e sem linha de produção contínua ou automatizada?', 27),
    ('Q28', 28, 'Fabricação de produtos e artefatos de madeira por processo simples', 'A atividade ficará restrita ao corte, aplainamento, torneamento, perfuração, lixamento, encaixe, prensagem mecânica, montagem e acabamento mecânico de madeira serrada, cortiça, bambu, palha, vime ou outros materiais trançados, sem desdobramento ou resserragem de madeira, fabricação de madeira laminada, MDF ou chapas compensadas, aglomeradas ou prensadas, tratamento químico da madeira, carbonização ou fabricação de carvão, briquetes, pellets, cavacos ou farinha de madeira?', 28),
    ('Q29', 29, 'Condições ambientais básicas do processo', 'A atividade não gerará efluentes líquidos industriais nem Resíduos Sólidos Classe I — Perigosos; o estabelecimento estará localizado em área dotada de sistema público de esgotamento sanitário ou contará com até 10 funcionários; e a atividade não dependerá de licença, autorização ou outro ato ambiental prévio?', 29),
    ('Q30', 30, 'Emissões atmosféricas', 'A atividade não gerará emissão de poluentes atmosféricos, inclusive poeiras ou material particulado, exceto as provenientes de equipamentos destinados exclusivamente à geração de calor por energia elétrica ou gás?', 30),
    ('Q31', 31, 'Fundição e tratamento de superfície de metais', 'A atividade não realizará fundição nem tratamento de superfície de metais?', 31),
    ('Q32', 32, 'Tingimento e uso de produtos químicos', 'A atividade não realizará tingimento nem utilizará produtos químicos como insumos do processo produtivo?', 32),
    ('Q33', 33, 'Emissões fugitivas', 'O empreendimento não possuirá fontes de emissões fugitivas?', 33),
    ('Q34', 34, 'Efluentes industriais de pequeno volume', 'A geração de efluentes líquidos industriais será de até 1.000 litros por dia, sem geração de Resíduos Sólidos Classe I — Perigosos, com manejo e destinação ambientalmente adequados dos efluentes e resíduos e sem que a atividade dependa de licença, autorização ou outro ato ambiental prévio?', 34),
    ('Q35', 35, 'Esgotamento sanitário ou pequeno porte', 'O estabelecimento estará localizado em área dotada de sistema público de esgotamento sanitário ou contará com até 10 funcionários?', 35),
    ('Q36', 36, 'Armazenamento de produtos perigosos', 'O estabelecimento não realizará armazenamento de produtos perigosos, inclusive amônia ou combustíveis, em quantidade ou condição sujeita a controle ambiental específico?', 36),
    ('Q37', 37, 'Captação de água', 'A atividade não realizará captação de água sujeita a outorga?', 37),
    ('Q38', 38, 'Formulação de produtos químicos por processo simples', 'A atividade ficará restrita à formulação, mistura, diluição, dissolução, fusão, saponificação, moldagem ou envase de matérias-primas previamente adquiridas, sem fabricação de princípios ativos ou intermediários químicos, produção de cloro ou álcalis, destilação ou outros processos químicos com geração de gases, vapores ou subprodutos perigosos?', 38),
    ('Q39', 39, 'Fabricação farmacêutica por processo simples', 'A atividade ficará restrita à formulação, manipulação, trituração, mistura, diluição, homogeneização, impregnação, encapsulamento, compressão, montagem, envase ou acondicionamento de princípios ativos, extratos e demais insumos previamente adquiridos, sem fabricação ou síntese de farmoquímicos ou princípios ativos, cultivo ou processamento de material biológico, fermentação ou processo biotecnológico, fabricação de soros, vacinas ou outros produtos biológicos, produção de substâncias radioativas ou esterilização industrial sujeita a controle ambiental específico?', 39),
    ('Q40', 40, 'Fabricação de artefatos de borracha por processo simples', 'A atividade ficará restrita ao corte, recorte, perfuração, prensagem mecânica, montagem e acabamento de borracha ou componentes previamente produzidos, sem beneficiamento de látex, preparação ou mistura de compostos de borracha, regeneração, vulcanização, espumação ou utilização de solventes, adesivos ou outros insumos químicos no processo?', 40),
    ('Q41', 41, 'Fabricação de produtos plásticos por processo simples', 'A atividade ficará restrita ao corte, recorte, dobra, perfuração, usinagem, conformação simples, selagem, soldagem térmica, montagem ou acabamento de filmes, chapas, perfis ou componentes plásticos previamente produzidos, sem fabricação de resinas, extrusão, injeção, sopro, rotomoldagem, expansão, espumação, laminação com resinas, reforço com fibra de vidro ou utilização de solventes, adesivos ou outros insumos químicos no processo?', 41),
    ('Q42', 42, 'Fabricação de artigos de vidro sem produção primária', 'A atividade será desenvolvida sem produção industrial de vidro, operações de espelhação ou produção de peças de fibra de vidro?', 42),
    ('Q43', 43, 'Transformação simples de vidro', 'A atividade ficará restrita ao corte, recorte, lapidação, perfuração, gravação, montagem ou acabamento mecânico de vidro ou cristal previamente produzido, sem fusão, sopro, têmpera, recozimento, laminação ou outro processo de transformação térmica?', 43),
    ('Q44', 44, 'Infraestrutura urbana', 'A atividade será desenvolvida em área urbana consolidada, atendida por sistemas públicos de abastecimento de água, esgotamento sanitário e coleta de resíduos sólidos?', 44),
    ('Q45', 45, 'Preparação de concreto e argamassa sem usina', 'A atividade ficará restrita à preparação de concreto ou argamassa, sem operação de usina de produção de concreto, dosagem industrial, carregamento de caminhões-betoneira ou bombeamento industrial de concreto?', 45),
    ('Q46', 46, 'Atividade exclusivamente administrativa', 'A atividade será exercida exclusivamente em escritório administrativo, sem que o estabelecimento execute, no local ou em campo, operações produtivas, industriais ou técnicas vinculadas à atividade declarada, e sem armazenamento de insumos, produtos perigosos ou resíduos vinculados à operação?', 46),
    ('Q47', 47, 'Tratamento químico de superfície', 'A atividade não realizará tratamento químico de superfície?', 47),
    ('Q48', 48, 'Montagem de armações metálicas', 'A atividade ficará restrita à montagem de armações metálicas para a construção civil, sem fabricação industrial dos componentes?', 48),
    ('Q49', 49, 'Corte e dobra manual de metais', 'A atividade ficará restrita ao corte e à dobra de metais realizados manualmente?', 49),
    ('Q50', 50, 'Montagem de circuitos eletrônicos', 'A atividade ficará restrita à montagem de circuitos eletrônicos ou de componentes em placas de circuitos impressos previamente fabricados, sem fabricação de placas, componentes eletrônicos ou semicondutores?', 50),
    ('Q51', 51, 'Montagem, instalação e ajuste de componentes', 'A atividade ficará restrita à montagem, instalação, ajuste ou substituição de peças, componentes, subconjuntos ou equipamentos previamente fabricados, sem fabricação ou transformação industrial desses elementos no estabelecimento?', 51),
    ('Q52', 52, 'Manutenção de motores elétricos', 'A atividade ficará restrita à manutenção e reparação de motores elétricos, sem manutenção ou reparação de geradores ou transformadores?', 52),
    ('Q53', 53, 'Gestão simplificada de rede de esgoto', 'A atividade ficará restrita à gestão ou operação de rede coletora e coletores-tronco de esgoto, sem operação de estação de tratamento de esgoto, estação elevatória, interceptor, emissário ou qualquer tratamento de efluentes?', 53),
    ('Q54', 54, 'Movimentação de solo de pequeno porte', 'A movimentação de solo será de até 100 m³?', 54),
    ('Q55', 55, 'Manutenção, lavagem e abastecimento de veículos e equipamentos', 'O estabelecimento não realizará manutenção, reparação, lavagem ou abastecimento de veículos, embarcações, aeronaves, máquinas ou equipamentos?', 55),
    ('Q56', 56, 'Serviços em veículos de passeio', 'Os serviços serão realizados exclusivamente em veículos de passeio?', 56),
    ('Q57', 57, 'Reforma de pneumáticos', 'A atividade não realizará reforma, recauchutagem, recapagem ou remoldagem de pneumáticos usados?', 57),
    ('Q58', 58, 'Desmanche de veículos', 'A atividade não realizará desmontagem ou desmanche de veículos automotores, motocicletas ou motonetas para obtenção ou comercialização de peças usadas?', 58),
    ('Q59', 59, 'Comércio sem beneficiamento', 'A atividade ficará restrita ao comércio e armazenamento dos produtos, sem beneficiamento, transformação, mistura, fracionamento, ensacamento ou recuperação no estabelecimento?', 59),
    ('Q60', 60, 'Abate no estabelecimento', 'A atividade não realizará abate de animais no estabelecimento?', 60),
    ('Q61', 61, 'Resíduos de serviços de saúde', 'Os Resíduos de Serviços de Saúde — RSS gerados serão segregados, acondicionados, armazenados e destinados de forma ambientalmente adequada, sem tratamento no estabelecimento?', 61),
    ('Q62', 62, 'Instalação ou operação de ferrovia', 'A atividade não envolverá instalação ou operação de ferrovia?', 62),
    ('Q63', 63, 'Transporte de resíduos e produtos perigosos', 'A atividade não realizará transporte de resíduos nem de produtos ou cargas classificados como perigosos?', 63),
    ('Q64', 64, 'Estacionamento de veículos leves', 'O estacionamento será destinado exclusivamente a veículos leves?', 64),
    ('Q65', 65, 'Armazenamento simples de mercadorias', 'A atividade ficará restrita ao armazenamento de mercadorias ou produtos devidamente acondicionados em embalagens ou unidades fechadas, sem armazenamento de resíduos, armazenamento a granel em silos ou tanques, câmaras frigoríficas ou sistemas de refrigeração industrial e sem beneficiamento, transformação, mistura, fracionamento, reembalagem ou processamento no estabelecimento?', 65),
    ('Q66', 66, 'Porte dos serviços de alimentação', 'A capacidade de atendimento ou fornecimento de alimentação será de até 200 pessoas?', 66),
    ('Q67', 67, 'Pesquisa científica de baixo impacto', 'A atividade será realizada sem coleta de indivíduos de fauna ou flora nativas no ambiente natural e sem experimentos, materiais ou organismos sujeitos a autorização ou controle ambiental específico?', 67),
    ('Q68', 68, 'Atendimento veterinário de baixo impacto', 'A atividade ficará restrita a consultas, vacinação, curativos, coleta de material e outros procedimentos ambulatoriais, sem internação ou hospedagem de animais, cirurgia, laboratório de análises, necropsia, uso de radiação ionizante ou geração de efluentes não sanitários?', 68),
    ('Q69', 69, 'Esterilização sujeita a controle específico', 'A atividade não realizará esterilização, desinfecção ou reprocessamento com óxido de etileno, radiação ionizante ou outro processo sujeito a licença, autorização ou controle específico?', 69),
    ('Q70', 70, 'Ensino exclusivamente virtual', 'A atividade de ensino será realizada exclusivamente de forma virtual, sem atendimento presencial de alunos, aulas presenciais ou atividades práticas no estabelecimento?', 70),
    ('Q71', 71, 'Estabelecimento de ensino de baixo impacto', 'O estabelecimento estará localizado sem intervenção em Área de Preservação Permanente, Reserva Legal, área úmida ou outra área ambientalmente protegida, sem supressão de vegetação nativa, atendido por sistemas públicos de abastecimento de água e esgotamento sanitário, não se caracterizará como campus universitário e possuirá área construída de até 40.000 m²?', 71),
    ('Q72', 72, 'Geração diária de RSS', 'A geração total de Resíduos de Serviços de Saúde — RSS será de até 30 litros por dia?', 72),
    ('Q73', 73, 'Geração reduzida de RSS', 'A geração total de Resíduos de Serviços de Saúde — RSS será de até 30 litros por semana?', 73),
    ('Q74', 74, 'Resíduos quimioterápicos e radioativos', 'A atividade não gerará resíduos quimioterápicos nem rejeitos radioativos enquadrados no Grupo C?', 74),
    ('Q75', 75, 'Porte hospitalar', 'O hospital possuirá até 80 leitos?', 75),
    ('Q76', 76, 'Porte do estabelecimento', 'A população total simultânea do estabelecimento será de até 200 pessoas?', 76),
    ('Q77', 77, 'Processamento de roupas de serviços de saúde', 'A atividade não realizará processamento de roupas hospitalares ou provenientes de serviços de saúde?', 77),
    ('Q78', 78, 'Efluentes líquidos de serviços de baixo impacto', 'Os efluentes líquidos gerados pela atividade serão destinados à rede pública de esgotamento sanitário ou, na sua ausência, a sistema de tratamento e disposição adequadamente dimensionado para a natureza e capacidade da atividade, sem lançamento de efluente bruto no solo, na rede pluvial ou em corpo hídrico?', 78),
    ('Q79', 79, 'Estudos geológicos sem mineração', 'A atividade não envolverá lavra, extração, beneficiamento mineral ou outra atividade de mineração?', 79),
    ('Q80', 80, 'Aluguel de banheiros químicos', 'A atividade não incluirá o aluguel de banheiros químicos?', 80),
    ('Q81', 81, 'Comércio atacadista de medicamentos veterinários', 'A atividade não comercializará produtos de uso veterinário de interesse da defesa agropecuária sujeitos a controle específico, inclusive vacinas, antígenos, alérgenos, antiparasitários, antimicrobianos, hormônios, vampiricidas ou produtos que contenham substâncias sujeitas a controle especial destinados a animais de produção?', 81)
) AS v(codigo, numero, titulo, texto, ordem)
JOIN amb_normas_versoes n
  ON n.codigo = 'MCR-RISCO-AMBIENTAL-CNAE23-2026-09-10';

INSERT INTO amb_classificacao_quesitos (
    classificacao_id,
    quesito_id,
    ordem
)
SELECT
    cl.id,
    q.id,
    v.ordem
FROM (VALUES
    ('0111301', 'Q01', 1),
    ('0111301', 'Q02', 2),
    ('0111302', 'Q01', 1),
    ('0111302', 'Q02', 2),
    ('0111303', 'Q01', 1),
    ('0111303', 'Q02', 2),
