JOIN amb_cnaes c
  ON c.versao_cnae = '2.3'
 AND c.codigo = v.cnae_codigo
JOIN amb_classificacoes_cnae cl
  ON cl.norma_versao_id = n.id
 AND cl.cnae_id = c.id
JOIN amb_quesitos q
  ON q.norma_versao_id = n.id
 AND q.codigo = v.quesito_codigo;

DO $m0016$
DECLARE
    v_norma_id BIGINT;
    v_total INTEGER;
BEGIN
    SELECT id
      INTO STRICT v_norma_id
      FROM amb_normas_versoes
     WHERE codigo = 'MCR-RISCO-AMBIENTAL-CNAE23-2026-09-10';

    SELECT count(*)
      INTO v_total
      FROM amb_cnaes
     WHERE versao_cnae = '2.3';

    IF v_total <> 1332 THEN
        RAISE EXCEPTION 'M0016: esperado 1332 CNAEs, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacoes_cnae
     WHERE norma_versao_id = v_norma_id;

    IF v_total <> 1332 THEN
        RAISE EXCEPTION 'M0016: esperado 1332 classificacoes, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacoes_cnae
     WHERE norma_versao_id = v_norma_id
       AND origem_enquadramento = 'ANEXO_I'
       AND classificacao_direta = 'ALTO';

    IF v_total <> 217 THEN
        RAISE EXCEPTION 'M0016: esperado 217 CNAEs no Anexo I, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacoes_cnae
     WHERE norma_versao_id = v_norma_id
       AND origem_enquadramento = 'ANEXO_II'
       AND classificacao_direta = 'BAIXO_A';

    IF v_total <> 354 THEN
        RAISE EXCEPTION 'M0016: esperado 354 CNAEs no Anexo II, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacoes_cnae
     WHERE norma_versao_id = v_norma_id
       AND origem_enquadramento = 'ANEXO_III'
       AND classificacao_direta IS NULL;

    IF v_total <> 761 THEN
        RAISE EXCEPTION 'M0016: esperado 761 CNAEs no Anexo III, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_quesitos
     WHERE norma_versao_id = v_norma_id;

    IF v_total <> 81 THEN
        RAISE EXCEPTION 'M0016: esperado 81 quesitos, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacao_quesitos cq
      JOIN amb_classificacoes_cnae cl
        ON cl.id = cq.classificacao_id
     WHERE cl.norma_versao_id = v_norma_id;

    IF v_total <> 2314 THEN
        RAISE EXCEPTION 'M0016: esperado 2314 vinculos, encontrado %', v_total;
    END IF;

    SELECT count(*)
      INTO v_total
      FROM amb_classificacoes_cnae cl
     WHERE cl.norma_versao_id = v_norma_id
       AND cl.origem_enquadramento = 'ANEXO_III'
       AND NOT EXISTS (
           SELECT 1
             FROM amb_classificacao_quesitos cq
            WHERE cq.classificacao_id = cl.id
       );

    IF v_total <> 0 THEN
        RAISE EXCEPTION 'M0016: % CNAEs do Anexo III ficaram sem quesitos', v_total;
    END IF;
END
$m0016$;
